function (vars) {
	var g = new GridWidget(vars.element, vars.dataSource);
	g.groupable = false;
	g.searchable = false;
	g.pageable = false;
	g.scrollable = false;
	g.editable = false;
	g.exports = true;
	
	g.columns = [
		{
			field: "Type",
			title: "[resource_shortdisplayname[Type]]",
			description: "[resource_description[Type]]",
			type: "string",
			width: 150
		},
		{
			field: "Currency",
			title: "[resource_shortdisplayname[Currency]]",
			description: "[resource_description[Currency]]",
			type: "string",
			width: 80
		},
		{
			field: "Gross",
			title: "[resource_shortdisplayname[Gross]]",
			description: "[resource_description[Gross]]",
			type: "number",
			format: "{0:" + type.moneyFormat + "}",
			width: 80
		},
		{
			field: "Net",
			title: "[resource_shortdisplayname[Net]]",
			description: "[resource_description[Net]]",
			type: "number",
			format: "{0:" + type.moneyFormat + "}",
			width: 80
		}
	];
	
	return g;
}
